function validate([nums, k]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 200000) return 'nums needs 1 to 200000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < -10000 || v > 10000)) return 'Each value in nums is a whole number from -10^4 to 10^4.';
  if (!Number.isInteger(k) || k < -1e9 || k > 1e9) return 'k is a whole number from -10^9 to 10^9.';
  return null;
}

