function maxSubArrayLen(nums, k) {
  const firstIndex = new Map();
  firstIndex.set(0, -1);
  let prefix = 0;
  let best = 0;

  for (let i = 0; i < nums.length; i++) {
    prefix += nums[i];
    if (firstIndex.has(prefix - k)) {
      best = Math.max(best, i - firstIndex.get(prefix - k));
    }
    if (!firstIndex.has(prefix)) {
      firstIndex.set(prefix, i);
    }
  }
  return best;
}

