function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 10);
  const span = size === 'large' ? (rand() < 0.5 ? 10000 : 5) : (rand() < 0.7 ? 3 : 10000);
  const nums = Array.from({ length: n }, () => Math.floor(rand() * (2 * span + 1)) - span);
  let k;
  if (rand() < 0.75) {
    const a = Math.floor(rand() * n), b = Math.floor(rand() * n);
    k = 0;
    for (let i = Math.min(a, b); i <= Math.max(a, b); i++) k += nums[i];
  } else {
    k = Math.floor(rand() * (4 * span + 1)) - 2 * span;
  }
  return [nums, k];
}
